def need(value, message):
    if not value:
        raise RuntimeError(message)


def identity(info):
    return (info.st_dev, info.st_ino, info.st_mode, info.st_uid, info.st_gid,
            info.st_nlink, info.st_size, info.st_mtime_ns, info.st_ctime_ns)


def directory_identity(info):
    return identity(info)[:5]


def files():
    value = json.loads(gzip.decompress(base64.b64decode(PAYLOAD)))
    need(isinstance(value, dict) and set(value) == ALLOWED, 'Unexpected release roster')
    return value


def checked_path(root, relative):
    root = Path(root)
    part = Path(relative)
    need(not part.is_absolute() and '..' not in part.parts and part.parts, 'Invalid release path')
    for item in (root, *[root / parent for parent in reversed(part.parents) if str(parent) != '.']):
        need(not item.is_symlink(), 'Symbolic path refused: ' + str(item))
    path = root / part
    need(not path.is_symlink(), 'Symbolic path refused: ' + str(path))
    need(path.parent.is_dir() and path.parent.resolve() == path.parent, 'Release parent is not a real directory')
    need(not path.exists() or path.is_file(), 'Unexpected release target')
    return path


class Target:
    """An opened application parent; mutations never traverse an absolute path."""
    def __init__(self, root, relative, stack):
        self.path = checked_path(root, relative)
        self.root = Path(root)
        self.allowed_uids = (0, self.root.stat().st_uid)
        self.chain = []
        root_info = self.root.lstat()
        self.root_before = directory_identity(root_info)
        fd = os.open(str(self.root), os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW)
        stack.callback(os.close, fd)
        need(directory_identity(os.fstat(fd)) == self.root_before, 'Application root changed')
        for name in Path(relative).parts[:-1]:
            before = os.stat(name, dir_fd=fd, follow_symlinks=False)
            need(stat.S_ISDIR(before.st_mode) and before.st_uid in self.allowed_uids
                 and not before.st_mode & 0o002, 'Unsafe application directory')
            child = os.open(name, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW, dir_fd=fd)
            stack.callback(os.close, child)
            need(directory_identity(os.fstat(child)) == directory_identity(before), 'Application directory changed')
            self.chain.append((fd, name, child, directory_identity(before)))
            fd = child
        self.fd, self.name, self.info, self.committed = fd, Path(relative).name, None, False
        self.check()

    def check(self):
        need(directory_identity(self.root.lstat()) == self.root_before, 'Application root changed')
        for parent, name, child, before in self.chain:
            need(directory_identity(os.stat(name, dir_fd=parent, follow_symlinks=False)) == before
                 and directory_identity(os.fstat(child)) == before, 'Application directory changed')

    def read(self):
        self.check()
        try:
            before = os.stat(self.name, dir_fd=self.fd, follow_symlinks=False)
        except FileNotFoundError:
            self.info = None
            return None
        need(stat.S_ISREG(before.st_mode) and before.st_uid in self.allowed_uids
             and before.st_nlink == 1 and not before.st_mode & 0o002
             and before.st_size <= 2 * 1024**2, 'Unsafe application file')
        fd = os.open(self.name, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK, dir_fd=self.fd)
        try:
            need(identity(os.fstat(fd)) == identity(before), 'Application file changed')
            parts, count = [], 0
            while count <= before.st_size:
                part = os.read(fd, min(65536, before.st_size + 1 - count))
                if not part:
                    break
                parts.append(part)
                count += len(part)
            need(count == before.st_size and identity(os.fstat(fd)) == identity(before)
                 and identity(os.stat(self.name, dir_fd=self.fd, follow_symlinks=False)) == identity(before),
                 'Application file changed')
        finally:
            os.close(fd)
        self.info = before
        self.check()
        return b''.join(parts)

    def atomic(self, data, uid, gid, mode, expected):
        self.committed = False
        need(self.read() == expected, 'Concurrent source change')
        temporary = '.website-orders-' + uuid.uuid4().hex
        fd = os.open(temporary, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW,
                     0o600, dir_fd=self.fd)
        try:
            with os.fdopen(fd, 'wb') as output:
                output.write(data)
                output.flush()
                os.fchown(output.fileno(), uid, gid)
                os.fchmod(output.fileno(), mode)
                os.fsync(output.fileno())
            self.check()
            need(self.read() == expected, 'Concurrent source change')
            if expected is None:
                os.link(temporary, self.name, src_dir_fd=self.fd, dst_dir_fd=self.fd,
                        follow_symlinks=False)
                self.committed = True
                os.unlink(temporary, dir_fd=self.fd)
            else:
                os.replace(temporary, self.name, src_dir_fd=self.fd, dst_dir_fd=self.fd)
                self.committed = True
            os.fsync(self.fd)
            self.check()
            need(self.read() == data, 'Committed source changed')
        finally:
            try:
                os.unlink(temporary, dir_fd=self.fd)
            except FileNotFoundError:
                pass

    def remove(self, expected):
        need(self.read() == expected, 'Concurrent source change')
        self.check()
        os.unlink(self.name, dir_fd=self.fd)
        os.fsync(self.fd)


def plan(root, entries):
    changes = []
    for relative, entry in entries.items():
        path = checked_path(root, relative)
        with ExitStack() as stack:
            current = Target(root, relative, stack).read()
        old = base64.b64decode(entry['old']) if entry['old'] is not None else None
        new = base64.b64decode(entry['new'])
        if current == new:
            continue
        if current != old:
            digest = hashlib.sha256(current).hexdigest() if current is not None else 'missing'
            raise RuntimeError('Unreviewed live change; no files replaced: ' + relative + ' sha256=' + digest)
        changes.append((relative, path, current, new))
    order = {name: number for number, name in enumerate(INSTALL_ORDER)}
    return sorted(changes, key=lambda item: order.get(item[0], len(order)))


def root_directory(path, create=False):
    if create and not path.exists() and not path.is_symlink():
        path.mkdir(mode=0o700)
    for parent in (*reversed(path.parents), path):
        info = parent.lstat()
        sticky = parent != path and bool(info.st_mode & stat.S_ISVTX)
        need(stat.S_ISDIR(info.st_mode) and info.st_uid == 0
             and (not info.st_mode & 0o022 or sticky), 'Unsafe private installer directory')
    need(path.resolve() == path and stat.S_IMODE(path.stat().st_mode) == 0o700, 'Unsafe backup directory')


def private_failure(label, stdout, stderr):
    path = BACKUPS / ('validation-' + uuid.uuid4().hex + '.log')
    fd = os.open(str(path), os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, 0o600)
    with os.fdopen(fd, 'w') as stream:
        stream.write(label + '\n' + stdout + '\n' + stderr)
    return str(path)


def save_private(path, data):
    fd = os.open(str(path), os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, 0o600)
    with os.fdopen(fd, 'wb') as stream:
        stream.write(data)
        stream.flush()
        os.fsync(stream.fileno())


def sync_directories(root):
    for parent, directories, _ in os.walk(str(root), topdown=False, followlinks=False):
        fd = os.open(parent, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW)
        try:
            os.fsync(fd)
        finally:
            os.close(fd)
    fd = os.open(str(root.parent), os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW)
    try:
        os.fsync(fd)
    finally:
        os.close(fd)


def run_owner(php, root, args, environment=None, timeout=180):
    env = {'PATH': '/usr/sbin:/usr/bin:/sbin:/bin', 'LANG': 'C', 'LC_ALL': 'C'}
    if environment:
        env.update(environment)
    result = subprocess.run(['runuser', '-u', 'fasakha', '--', str(php)] + list(args),
                            cwd=str(root), env=env, stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                            stdin=subprocess.DEVNULL, universal_newlines=True, timeout=timeout)
    if result.returncode:
        log = private_failure('PHP verification failed', result.stdout, result.stderr)
        raise RuntimeError('Application verification failed; private log: ' + log)
    return result.stdout


def load_lock_helper():
    path = Path(__file__).absolute().parent / 'go_erp_release_retention_root.py'
    before = path.lstat()
    need(stat.S_ISREG(before.st_mode) and before.st_uid == 0 and before.st_nlink == 1
         and not before.st_mode & 0o022 and 0 < before.st_size < 1024**2, 'Unsafe coordination helper')
    fd = os.open(str(path), os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK)
    try:
        need(identity(before) == identity(os.fstat(fd)), 'Coordination helper changed')
        raw = b''
        while len(raw) <= before.st_size:
            part = os.read(fd, 65536)
            if not part:
                break
            raw += part
        need(len(raw) == before.st_size and identity(os.fstat(fd)) == identity(before)
             and identity(path.lstat()) == identity(before), 'Coordination helper changed')
    finally:
        os.close(fd)
    need(hashlib.sha256(raw).hexdigest() == HELPER_SHA256, 'Coordination helper pin mismatch')
    spec = importlib.util.spec_from_file_location('website_order_install_locks', str(path))
    helper = importlib.util.module_from_spec(spec)
    exec(compile(raw, str(path), 'exec'), helper.__dict__)
    return helper


def private_tree(source, target, gid):
    """Copy source descriptors into a private stage without pathname traversal."""
    source, target = Path(source), Path(target)
    with ExitStack() as stack:
        chains = []
        def opened_directory(path, private=False):
            need(path.is_absolute() and '..' not in path.parts, 'Invalid test directory path')
            fd = os.open('/', os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW)
            stack.callback(os.close, fd)
            for name in path.parts[1:]:
                before = os.stat(name, dir_fd=fd, follow_symlinks=False)
                need(stat.S_ISDIR(before.st_mode), 'Linked test source directory refused')
                if private:
                    sticky = bool(before.st_mode & stat.S_ISVTX)
                    need(before.st_uid == 0 and (not before.st_mode & 0o022 or sticky),
                         'Unsafe private test directory')
                child = os.open(name, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW, dir_fd=fd)
                stack.callback(os.close, child)
                need(directory_identity(os.fstat(child)) == directory_identity(before), 'Test directory changed')
                chains.append((fd, name, child, directory_identity(before)))
                fd = child
            if private:
                info = os.fstat(fd)
                need(info.st_uid == 0 and not info.st_mode & 0o022, 'Unsafe private test directory')
            return fd

        source_fd = opened_directory(source)
        source_uid = os.fstat(source_fd).st_uid
        parent_fd = opened_directory(target.parent, private=True)
        try:
            os.mkdir(target.name, mode=0o750, dir_fd=parent_fd)
        except FileExistsError:
            pass
        before = os.stat(target.name, dir_fd=parent_fd, follow_symlinks=False)
        need(stat.S_ISDIR(before.st_mode) and before.st_uid == 0 and not before.st_mode & 0o022,
             'Unsafe test output directory')
        target_fd = os.open(target.name, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW, dir_fd=parent_fd)
        stack.callback(os.close, target_fd)
        need(directory_identity(os.fstat(target_fd)) == directory_identity(before), 'Test output directory changed')
        os.fchown(target_fd, 0, gid)
        os.fchmod(target_fd, 0o750)

        def copy_directory(src, dst):
            directory_before = identity(os.fstat(src))
            names = sorted(os.listdir(src))
            for name in names:
                info = os.stat(name, dir_fd=src, follow_symlinks=False)
                need(info.st_uid in (0, source_uid), 'Unexpected test source owner')
                if stat.S_ISDIR(info.st_mode):
                    child_src = os.open(name, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW, dir_fd=src)
                    try:
                        need(identity(os.fstat(child_src)) == identity(info), 'Test source directory changed')
                        os.mkdir(name, mode=0o750, dir_fd=dst)
                        child_dst = os.open(name, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW, dir_fd=dst)
                        try:
                            output_info = os.fstat(child_dst)
                            need(output_info.st_uid == 0 and not output_info.st_mode & 0o022,
                                 'Unsafe test output directory')
                            os.fchown(child_dst, 0, gid)
                            os.fchmod(child_dst, 0o750)
                            copy_directory(child_src, child_dst)
                        finally:
                            os.close(child_dst)
                        need(identity(os.stat(name, dir_fd=src, follow_symlinks=False)) == identity(info),
                             'Test source directory changed')
                    finally:
                        os.close(child_src)
                    continue
                need(stat.S_ISREG(info.st_mode) and info.st_nlink == 1,
                     'Special, hardlinked or linked test source file refused')
                descriptor = os.open(name, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK, dir_fd=src)
                try:
                    need(identity(os.fstat(descriptor)) == identity(info), 'Test source changed')
                    output_fd = os.open(name, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW,
                                        0o600, dir_fd=dst)
                    with os.fdopen(output_fd, 'wb') as output:
                        total = 0
                        while True:
                            block = os.read(descriptor, 65536)
                            if not block:
                                break
                            total += len(block)
                            need(total <= info.st_size, 'Test source changed')
                            output.write(block)
                        os.fchown(output.fileno(), 0, gid)
                        os.fchmod(output.fileno(), 0o640)
                    need(total == info.st_size and identity(os.fstat(descriptor)) == identity(info)
                         and identity(os.stat(name, dir_fd=src, follow_symlinks=False)) == identity(info),
                         'Test source changed')
                finally:
                    os.close(descriptor)
            need(identity(os.fstat(src)) == directory_before, 'Test source directory changed')

        copy_directory(source_fd, target_fd)
        for parent, name, child, before in chains:
            need(directory_identity(os.stat(name, dir_fd=parent, follow_symlinks=False)) == before
                 and directory_identity(os.fstat(child)) == before, 'Test source ancestor changed')


def owner_file(path, data, gid):
    path.parent.mkdir(mode=0o750, parents=True, exist_ok=True)
    for directory in (path.parent,):
        os.chown(str(directory), 0, gid)
        os.chmod(str(directory), 0o750)
    path.write_bytes(data)
    os.chown(str(path), 0, gid)
    os.chmod(str(path), 0o640)


def isolated_checks(php, root, entries, stage, gid):
    version = run_owner(php, root, ['-r', 'echo (PHP_VERSION_ID>=80000 && extension_loaded("pdo_sqlite")) ? "READY" : "UNAVAILABLE";'])
    need(version == 'READY', 'PHP 8 with pdo_sqlite is required for isolated verification')
    private_tree(root / 'app', stage / 'app', gid)
    (stage / 'database').mkdir(mode=0o750)
    os.chown(str(stage / 'database'), 0, gid)
    private_tree(root / 'database/migrations', stage / 'database/migrations', gid)
    for relative, entry in entries.items():
        path = stage / relative
        parent = path.parent
        chain = []
        while parent != stage:
            chain.append(parent)
            parent = parent.parent
        for directory in reversed(chain):
            directory.mkdir(mode=0o750, exist_ok=True)
            os.chown(str(directory), 0, gid)
            os.chmod(str(directory), 0o750)
        owner_file(path, base64.b64decode(entry['new']), gid)
        if relative.endswith('.php') and not relative.endswith('.blade.php'):
            run_owner(php, root, ['-l', str(path)])
    test = gzip.decompress(base64.b64decode(TEST_PAYLOAD))
    owner_file(stage / 'tests/website_order_board_test.php', test, gid)
    output = run_owner(php, root, TEST_FLAGS + [str(stage / 'tests/website_order_board_test.php')],
                       {'WEBSITE_BOARD_TEST_AUTOLOAD': str(root / 'vendor/autoload.php')}, timeout=240)
    match = re.search(r'Website order board checks passed: ([0-9]+)\s*$', output)
    need(match is not None and int(match.group(1)) >= 49, 'Isolated website checks did not complete')
    print('ISOLATED_WEBSITE_BOARD_CHECKS_PASSED=' + match.group(1), flush=True)
    return int(match.group(1))


