def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--apply', action='store_true')
    options = parser.parse_args()
    need(os.geteuid() == 0 and socket.gethostname().split('.')[0] == 'srv1836524', 'Run as root on srv1836524')
    os.umask(0o077)
    owner = pwd.getpwnam('fasakha')
    need(ROOT.is_dir() and not ROOT.is_symlink() and ROOT.resolve() == ROOT
         and ROOT.stat().st_uid == owner.pw_uid, 'Unexpected application root')
    need(PHP.is_file() and os.access(str(PHP), os.X_OK), 'PHP 8.2 is unavailable')
    root_directory(BACKUPS, create=True)
    helper = load_lock_helper()
    with ExitStack() as stack:
        held = [helper.lock_file(BACKUPS / 'install.lock', stack)]
        for path in (Path('/var/lib/go-erp-manual-updates/private/install.lock'),
                     Path('/var/lib/go-erp-manual-updates/private/worker.lock'),
                     Path('/var/lib/go-erp-live-updates/watcher.lock')):
            held.append(helper.lock_file(path, stack))
        publication = helper.Directory(ROOT / 'storage/app/desktop-updates', stack)
        fcntl.flock(publication.fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
        held.append(helper.lock_file(Path('/var/lib/go-erp-manual-updates/shared/.downloads.lock'), stack))
        entries = files()
        changes = plan(ROOT, entries)
        with tempfile.TemporaryDirectory(prefix='website-order-candidate-', dir='/var/tmp') as temporary:
            stage = Path(temporary)
            os.chown(str(stage), 0, owner.pw_gid)
            os.chmod(str(stage), 0o750)
            verifier = stage / 'verify.php'
            owner_file(verifier, VERIFY.encode(), owner.pw_gid)
            before = json.loads(run_owner(PHP, ROOT, [str(verifier), str(ROOT), 'before']))
            checked = isolated_checks(PHP, ROOT, entries, stage, owner.pw_gid)
            need(plan(ROOT, entries) == changes, 'Concurrent source change')
            helper.check_locks(held)
            publication.check()
            if not options.apply:
                print('WEBSITE_APP_ORDERS_CHECK_OK files=' + str(len(changes)))
                print(json.dumps(before, sort_keys=True))
                return 0
            backup = Path(tempfile.mkdtemp(prefix=datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%SZ-'), dir=str(BACKUPS)))
            metadata, targets = {}, {}
            for relative, _, old, new in changes:
                target = Target(ROOT, relative, stack)
                need(target.read() == old, 'Concurrent source change')
                info = target.info
                metadata[relative] = {'existed': old is not None, 'uid': info.st_uid if info else owner.pw_uid,
                    'gid': info.st_gid if info else owner.pw_gid, 'mode': stat.S_IMODE(info.st_mode) if info else 0o644,
                    'old_sha256': hashlib.sha256(old).hexdigest() if old is not None else None,
                    'new_sha256': hashlib.sha256(new).hexdigest()}
                if old is not None:
                    saved = backup / relative
                    saved.parent.mkdir(parents=True, exist_ok=True)
                    save_private(saved, old)
                targets[relative] = target
            save_private(backup / 'metadata.json', json.dumps(metadata, sort_keys=True, indent=2).encode())
            sync_directories(backup)
            written = []
            try:
                for relative, _, old, new in changes:
                    helper.check_locks(held)
                    publication.check()
                    target = targets[relative]
                    try:
                        target.atomic(new, owner.pw_uid, owner.pw_gid, metadata[relative]['mode'], old)
                    finally:
                        if target.committed:
                            written.append((relative, old, new))
                run_owner(PHP, ROOT, ['artisan', 'route:clear'])
                run_owner(PHP, ROOT, ['artisan', 'view:clear'])
                after = json.loads(run_owner(PHP, ROOT, [str(verifier), str(ROOT), 'installed']))
                for relative, _, _, new in changes:
                    need(targets[relative].read() == new, 'Committed source changed')
                helper.check_locks(held)
                publication.check()
                (backup / 'receipt.json').write_text(json.dumps({'installed': True, 'files': list(entries),
                    'isolated_checks': checked, 'before': before, 'after': after}, sort_keys=True, indent=2))
            except BaseException:
                conflicts = []
                for relative, old, new in reversed(written):
                    target = targets[relative]
                    try:
                        need(target.read() == new, 'Source changed before rollback')
                        if old is None:
                            target.remove(new)
                        else:
                            saved = metadata[relative]
                            target.atomic(old, saved['uid'], saved['gid'], saved['mode'], new)
                    except Exception:
                        conflicts.append(relative)
                for command in ('route:clear', 'view:clear'):
                    try:
                        run_owner(PHP, ROOT, ['artisan', command])
                    except Exception:
                        pass
                (backup / 'rollback.json').write_text(json.dumps({'rollback_conflicts': conflicts}, sort_keys=True))
                print('WEBSITE_APP_ORDERS_BACKUP=' + str(backup), flush=True)
                raise
            print('WEBSITE_APP_ORDERS_READY files=' + str(len(changes)))
            print(json.dumps(after, sort_keys=True))
            print('WEBSITE_APP_ORDERS_BACKUP=' + str(backup))
    return 0


if __name__ == '__main__':
    try:
        raise SystemExit(main())
    except BlockingIOError:
        print('WEBSITE_APP_ORDERS_UPDATE_BUSY_NO_SOURCE_FILES_REPLACED')
        raise SystemExit(75)
    except Exception as error:
        print('WEBSITE_APP_ORDERS_STOPPED: ' + str(error))
        raise SystemExit(1)
